#pragma once
#include <juce_core/juce_core.h>

class TwinboxProcessor;

// Genre preset libraries embedded in the plug-in (generated by tools/gen_presets.py).
//  Section A item: drum-synth kit (8 patches + names) + one pattern (up to 64 steps) + swing / fill rate
//  Section B item: sample kit (samples, voice + FX parameters) + patterns A-D
class PresetLibrary
{
public:
    struct Item { juce::String name, genre; int bpm = 120; juce::var data; juce::String level; };
    static const PresetLibrary& get();
    const std::vector<Item>& items (int section) const { return section == 0 ? a : b; }
    juce::StringArray genres() const;

    static void applyA (TwinboxProcessor& p, const Item& it, int slot, bool kit, bool pattern, bool tempo);
    static void applyB (TwinboxProcessor& p, const Item& it, bool kit, bool patterns, bool tempo);

private:
    PresetLibrary();
    std::vector<Item> a, b;
};
